import { spawnSync } from 'node:child_process';

const exe = '/workspace/dataset/test12_executable';
const cases = [
  ['no_args', []],
  ['missing_d', ['--a', '1', '--b', '2', '--c', '3']],
  ['unknown_arg', ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5']],
