  ['valid', ['--a', '1', '--b', '2', '--c', '3', '--d', '4']],
];

for (const [name, args] of cases) {
  const res = spawnSync(exe, args, { encoding: 'utf8' });
  const out = {
    case: name,
    args,
    status: res.status,
    signal: res.signal,
    error: res.error ? String(res.error) : null,
    stdout: res.stdout,
    stderr: res.stderr,
  };
  console.log(JSON.stringify(out, null, 2));
}
